#include "ENGINE/Source/Os/W32/osfile.h"
#include <filesystem>
#include <string>
#include <cstring>
namespace fs=std::filesystem;namespace{FILETIME ToFt(const OSFILETIME*t){std::uint64_t v=t?t->m_value:0;return{DWORD(v),DWORD(v>>32)};}OSFILETIME FromFt(const FILETIME&t){return{(std::uint64_t(t.dwHighDateTime)<<32)|t.dwLowDateTime};}}
void* OsCreateFile(const char*p,unsigned a,unsigned s,unsigned d,unsigned f,unsigned){HANDLE h=CreateFileA(p,a,s,nullptr,d,f,nullptr);return h==INVALID_HANDLE_VALUE?nullptr:h;}void OsCloseFile(void*h){if(h)CloseHandle(h);}BOOL OsFileExists(const char*p){DWORD a=p?GetFileAttributesA(p):INVALID_FILE_ATTRIBUTES;return a!=INVALID_FILE_ATTRIBUTES&&!(a&FILE_ATTRIBUTE_DIRECTORY);}BOOL OsDirectoryExists(const char*p){DWORD a=p?GetFileAttributesA(p):INVALID_FILE_ATTRIBUTES;return a!=INVALID_FILE_ATTRIBUTES&&(a&FILE_ATTRIBUTE_DIRECTORY);}BOOL OsReadFile(void*h,void*b,DWORD n,unsigned*r){return ReadFile(h,b,n,reinterpret_cast<DWORD*>(r),nullptr);}BOOL OsWriteFile(void*h,const void*b,DWORD n,unsigned*w){return WriteFile(h,b,n,reinterpret_cast<DWORD*>(w),nullptr);}BOOL OsFlushFile(void*h){return FlushFileBuffers(h);}DWORD OsSetFilePointer(void*h,std::int64_t d,DWORD m){LARGE_INTEGER x{},o{};x.QuadPart=d;return SetFilePointerEx(h,x,&o,m)?DWORD(o.QuadPart):INVALID_SET_FILE_POINTER;}DWORD OsGetFileSize(void*h){return GetFileSize(h,nullptr);}
BOOL OsGetFileTime(void*h,OSFILETIME*c,OSFILETIME*a,OSFILETIME*w){FILETIME cf{},af{},wf{};BOOL ok=GetFileTime(h,c?&cf:nullptr,a?&af:nullptr,w?&wf:nullptr);if(ok){if(c)*c=FromFt(cf);if(a)*a=FromFt(af);if(w)*w=FromFt(wf);}return ok;}BOOL OsSetFileTime(void*h,const OSFILETIME*c,const OSFILETIME*a,const OSFILETIME*w){FILETIME cf=ToFt(c),af=ToFt(a),wf=ToFt(w);return SetFileTime(h,c?&cf:nullptr,a?&af:nullptr,w?&wf:nullptr);}BOOL OsSetEndOfFile(void*h){return SetEndOfFile(h);}DWORD OsGetFileAttributes(const char*p){return GetFileAttributesA(p);}BOOL OsSetFileAttributes(const char*p,DWORD a){return SetFileAttributesA(p,a);}BOOL OsMoveFile(const char*a,const char*b){return MoveFileA(a,b);}BOOL OsCopyFile(const char*a,const char*b,int fail){return CopyFileA(a,b,fail);}BOOL OsDeleteFile(const char*p){return DeleteFileA(p);}BOOL OsCreateDirectory(const char*p,int recursive){if(!recursive)return CreateDirectoryA(p,nullptr);std::error_code e;return fs::create_directories(p,e)||fs::is_directory(p,e);}BOOL OsRemoveDirectory(const char*p){return RemoveDirectoryA(p);}BOOL OsRemoveDirectoryRecurse(const char*p,unsigned){std::error_code e;fs::remove_all(p,e);return !e;}BOOL OsSetCurrentDirectory(const char*p){return SetCurrentDirectoryA(p);}DWORD OsGetCurrentDirectory(char*b,DWORD n){return GetCurrentDirectoryA(n,b);}void UTF16ToUTF8(char*d,const wchar_t*s,unsigned n){if(d&&n)WideCharToMultiByte(CP_UTF8,0,s?s:L"",-1,d,n,nullptr,nullptr);}
int OsFileList(const char*pattern,OS_FILE_CALLBACK cb,void*u,int hidden){if(!pattern||!cb)return 0;WIN32_FIND_DATAA f{};HANDLE h=FindFirstFileA(pattern,&f);if(h==INVALID_HANDLE_VALUE)return 0;int count=0;do{if(!hidden&&(f.dwFileAttributes&FILE_ATTRIBUTE_HIDDEN))continue;OS_FILE_DATA d{};d.size=f.nFileSizeLow;d.flags=f.dwFileAttributes;strncpy_s(d.fileName,f.cFileName,_TRUNCATE);++count;if(!cb(&d,u))break;}while(FindNextFileA(h,&f));FindClose(h);return count;}
BOOL OsFileAssocGetIdentifier(char*b,unsigned n){if(!b||!n)return FALSE;DWORD size=n;return RegGetValueA(HKEY_CLASSES_ROOT,".wow",nullptr,RRF_RT_REG_SZ,nullptr,b,&size)==ERROR_SUCCESS;}BOOL OsFileAssocSetIdentifier(const char*v){return RegSetKeyValueA(HKEY_CLASSES_ROOT,".wow",nullptr,REG_SZ,v,DWORD(strlen(v)+1))==ERROR_SUCCESS;}BOOL OsFileAssocGetValue(const char*t,char*b,unsigned n){DWORD size=n;return RegGetValueA(HKEY_CLASSES_ROOT,t,nullptr,RRF_RT_REG_SZ,nullptr,b,&size)==ERROR_SUCCESS;}BOOL OsFileAssocSetValue(const char*t,const char*v){return RegSetKeyValueA(HKEY_CLASSES_ROOT,t,nullptr,REG_SZ,v,DWORD(strlen(v)+1))==ERROR_SUCCESS;}std::uint64_t OsFileFreeSpace(const char*p){ULARGE_INTEGER free{};return GetDiskFreeSpaceExA(p,&free,nullptr,nullptr)?free.QuadPart:0;}
int __fastcall EnumRemoveDirectoryRecurse(const char* path,int){return path&&OsRemoveDirectoryRecurse(path,0);}
